//! 🎟️ Actual native pair lending preserves its unique outer slot and refuses foreign or aliased ownership.
use semio_framework_job_context::{OriginalNativeRetirement,OriginalNativeLease,OriginalTurnFailure,StepContext,OperationId,Generation};
use semio_framework_job_testing_caller::OriginalJobFixtureCaller;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
struct Probe{closed:bool}
impl OriginalNativeRetirement for Probe{fn close_on_source(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if self.closed{return Ok(true)}let progress=RetainedCloneProgress{copied_items:1,copied_bytes:std::mem::size_of::<bool>(),..Default::default()};if cx.retirement_should_yield()||!progress.fits(cx.retained_grant())||cx.fuel_remaining()==0{return Ok(false)}cx.consume_retained(progress)?;cx.consume_fuel(1);self.closed=true;Ok(true)}fn terminal_is_empty(&self)->bool{self.closed}}
fn clock()->Option<u64>{Some(1)}
fn admit(caller:&mut OriginalJobFixtureCaller,grant:RetainedCloneGrant)->Option<OriginalNativeLease<Probe>>{let mut input=Some(Probe{closed:false});let mut output=None;for _ in 0..4096{if caller.refreshed_turn(grant,|cx|cx.admit_original_native(&mut input,&mut output)).unwrap(){break}}assert!(input.is_none()&&output.is_some());output}
#[test]fn native_pair_slot_moves_the_actual_unique_lease_and_preserves_denied_owners(){let stock=RetainedCloneGrant{maximum_items:1_000_000,maximum_copy_bytes:32_000_000,maximum_capacity_bytes:32_000_000,maximum_release_bytes:32_000_000,maximum_depth:128};let grant=RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:1_000_000,maximum_capacity_bytes:1_000_000,maximum_release_bytes:1_000_000,maximum_depth:64};let mut caller=OriginalJobFixtureCaller::admit(OperationId(908),Generation(1),stock,clock,100_000_000,10_000_000);caller.admit_return_table();let mut foreign=OriginalJobFixtureCaller::admit(OperationId(909),Generation(1),stock,clock,100_000_000,10_000_000);let mut left=admit(&mut caller,grant);let mut right=admit(&mut caller,grant);let mut other=admit(&mut foreign,grant);let mut entered=false;let(result,heap)=observe(||caller.refreshed_turn(grant,|cx|left.as_mut().unwrap().with_native_pair_slot(&mut other,cx,|_,_,_,_|{entered=true;Ok(())})));assert!(result.is_err());assert!(!entered);assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());assert!(other.is_some());let right_id=right.as_ref().unwrap().recipient_identity();let mut alias=None;for _ in 0..4096{if caller.refreshed_turn(grant,|cx|right.as_ref().unwrap().lend(cx,&mut alias)).unwrap(){break}}assert!(alias.is_some());let(result,heap)=observe(||caller.refreshed_turn(grant,|cx|left.as_mut().unwrap().with_native_pair_slot(&mut right,cx,|_,_,_,_|{entered=true;Ok(())})));assert!(result.is_err());assert!(!entered);assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());assert_eq!(right.as_ref().unwrap().recipient_identity(),right_id);for _ in 0..4096{if caller.refreshed_turn(grant,|cx|cx.with_original_retirement(|cx|OriginalNativeLease::return_slot_step(&mut alias,cx))).unwrap(){break}}for _ in 0..128{caller.refreshed_turn(grant,|cx|cx.with_original_retirement(|cx|cx.close_original_native_step())).unwrap();}let mut moved=None;let(result,heap)=observe(||caller.refreshed_turn(grant,|cx|left.as_mut().unwrap().with_native_pair_slot(&mut right,cx,|producer,fault,slot,cx|{assert_eq!(fault.recipient_identity(),right_id);assert_ne!(producer.recipient_identity(),right_id);assert_eq!(slot.as_ref().unwrap().recipient_identity(),right_id);let bytes=2*std::mem::size_of::<Option<OriginalNativeLease<Probe>>>();cx.consume_retained(RetainedCloneProgress{copied_items:2,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(2);moved=slot.take();entered=true;Ok(())})));assert!(result.unwrap());assert!(entered);assert_eq!(heap,(0,0));assert!(right.is_none());assert_eq!(moved.as_ref().unwrap().recipient_identity(),right_id);for lease in[&mut left,&mut moved]{for _ in 0..4096{if caller.refreshed_turn(grant,|cx|cx.with_original_retirement(|cx|OriginalNativeLease::return_slot_step(lease,cx))).unwrap(){break}}}for _ in 0..4096{if foreign.refreshed_turn(grant,|cx|cx.with_original_retirement(|cx|OriginalNativeLease::return_slot_step(&mut other,cx))).unwrap(){break}}foreign.retire(grant);caller.retire(grant);}

#[test]fn native_admission_has_no_effect_when_any_actual_birth_currency_is_absent(){let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/admission.json")).unwrap();let stock=RetainedCloneGrant{maximum_items:100000,maximum_copy_bytes:32000000,maximum_capacity_bytes:32000000,maximum_release_bytes:32000000,maximum_depth:128};let mut caller=OriginalJobFixtureCaller::admit(OperationId(910),Generation(1),stock,clock,10000000,10000000);caller.admit_return_table();let mut input=Some(Probe{closed:false});let mut output=None;for row in law["cases"].as_array().unwrap(){let mut grant=stock;match row["axis"].as_str().unwrap(){"items"=>grant.maximum_items=0,"copy"=>grant.maximum_copy_bytes=0,"capacity"=>grant.maximum_capacity_bytes=0,"release"=>grant.maximum_release_bytes=0,"depth"=>grant.maximum_depth=0,_=>unreachable!()}let(result,heap)=observe(||caller.refreshed_turn(grant,|cx|{let admitted=cx.admit_original_native(&mut input,&mut output)?;assert!(!cx.original_source_parent()?.native_sources_pending());Ok(admitted)}));assert_eq!(result.unwrap(),row["admitted"].as_bool().unwrap());assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());assert!(input.is_some()&&output.is_none());}let mut lease=admit(&mut caller,stock);for _ in 0..4096{if caller.refreshed_turn(stock,|cx|cx.with_original_retirement(|cx|OriginalNativeLease::return_slot_step(&mut lease,cx))).unwrap(){break}}caller.retire(stock);}

#[test]fn native_return_clears_only_its_funded_slot_then_observes_the_actual_prepaid_bank_cell(){let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/capture.json")).unwrap();let stock=RetainedCloneGrant{maximum_items:100000,maximum_copy_bytes:32000000,maximum_capacity_bytes:32000000,maximum_release_bytes:32000000,maximum_depth:128};let mut caller=OriginalJobFixtureCaller::admit(OperationId(911),Generation(1),stock,clock,10000000,10000000);caller.admit_return_table();let mut owner=admit(&mut caller,stock);let identity=owner.as_ref().unwrap().recipient_identity();let(result,heap)=observe(||caller.refreshed_turn(RetainedCloneGrant{maximum_copy_bytes:law["deniedCopyBytes"].as_u64().unwrap()as usize,..stock},|cx|OriginalNativeLease::return_slot_step(&mut owner,cx)));assert!(!result.unwrap());assert!(owner.is_some());assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());let(result,heap)=observe(||caller.refreshed_turn(stock,|cx|OriginalNativeLease::return_slot_step(&mut owner,cx)));assert!(result.unwrap());assert!(owner.is_none());assert_eq!(heap,(0,0));assert_eq!(caller.receipt().copied_items,law["slotClearItems"].as_u64().unwrap()as usize);assert_eq!(caller.receipt().copied_bytes,std::mem::size_of::<Option<OriginalNativeLease<Probe>>>());caller.refreshed_turn(stock,|cx|{assert!(cx.original_source_parent()?.native_sources_pending());assert!(cx.original_native_recipient_closed(identity)?.is_none());assert!(cx.original_native_retired_witness(identity)?.is_none());Ok(())}).unwrap();for _ in 0..4096{if caller.refreshed_turn(stock,|cx|cx.with_original_retirement(|cx|cx.close_original_native_step())).unwrap(){break}}caller.refreshed_turn(stock,|cx|{assert!(!cx.original_source_parent()?.native_sources_pending());assert!(cx.original_native_retired_witness(identity)?.is_some());Ok(())}).unwrap();caller.retire(stock);}
